element.style.display = 'none';

var parent = element.parentElement;
if (!parent || parent.dataset.replaced) return;
parent.dataset.replaced = 'true';

var container = document.createElement('div');
container.className = 'b_ans text-replacement';
container.style.cssText = 'padding:16px 0; border-top:1px solid #e0e0e0; border-bottom:1px solid #e0e0e0; margin:8px 0;';

var heading = document.createElement('h2');
heading.style.cssText = 'font-size:16px; font-weight:600; margin:0 0 12px 0; color:#111;';
heading.textContent = 'Images of Cats';
container.appendChild(heading);

var linkList = document.createElement('ul');
linkList.style.cssText = 'list-style:none; padding:0; margin:0; display:flex; flex-wrap:wrap; gap:8px;';

var slides = parent.querySelectorAll('.rel_ent_w .slide .rel_ent');
slides.forEach(function(slide) {
  var href = slide.getAttribute('href') || '#';
  var text = slide.getAttribute('title') || '';
  if (!text) return;

  var li = document.createElement('li');
  var a = document.createElement('a');
  a.href = href;
  a.textContent = text;
  a.target = '_blank';
  a.style.cssText = 'display:inline-block; padding:6px 12px; background:#f3f3f3; border-radius:4px; text-decoration:none; color:#1155cc; font-size:14px;';
  li.appendChild(a);
  linkList.appendChild(li);
});

container.appendChild(linkList);
parent.parentNode.insertBefore(container, parent.nextSibling);

