var linkList = document.createElement('ul');
linkList.style.cssText = 'list-style:none; padding:0; margin:0; display:flex; flex-wrap:wrap; gap:8px;';

var carouselItems = parent.querySelectorAll('.iacf_crsl li[data-wptds-carousel-item]');
carouselItems.forEach(function(item) {
  var infoDiv = item.querySelector('.iacf_info .iacf_tt a');
  var linkEl = item.querySelector('.iacfmit > a');

  var href = '';
  var text = '';

  if (infoDiv) {
    href = infoDiv.getAttribute('href') || '#';
    text = infoDiv.textContent.trim();
  } else if (linkEl) {
    href = linkEl.getAttribute('href') || '#';
    text = linkEl.getAttribute('aria-label') || '';
  }

  if (!text) return;

  var li = document.createElement('li');
  var a = document.createElement('a');
  a.href = href;
  a.textContent = text;
  a.target = '_blank';
